using Microsoft.EntityFrameworkCore;

// Cosmos DB provider - EF Core 9 breaking changes addressed:
// 1. Discriminator property renamed from "Discriminator" to "$type"
// 2. id property no longer contains discriminator prefix
// 3. Sync I/O no longer supported — must use async methods

class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Session>(b =>
        {
            b.ToContainer("Sessions");

            // Fix 1: Existing documents use "Discriminator" — EF Core 9 defaults to "$type".
            // Preserve the old property name for backward compatibility.
            b.HasDiscriminator<string>("Discriminator");

            // Fix 2: Existing documents use "Session|<key>" format for id.
            // EF Core 9 defaults to just the key value. Preserve old format.
            b.HasRootDiscriminatorInJsonId(true);
        });
    }
}

// Fix 3: Sync I/O example — all Cosmos queries must be async in EF Core 9.
class CosmosQueryService
{
    // BEFORE (breaks in EF Core 9 — throws InvalidOperationException):
    //   var sessions = db.Sessions.ToList();
    //   db.SaveChanges();
    //
    // AFTER:
    async Task<List<Session>> GetSessionsAsync(CosmosDbContext db)
    {
        return await db.Sessions.ToListAsync();
    }

    async Task SaveAsync(CosmosDbContext db)
    {
        await db.SaveChangesAsync();
    }
}

class Session
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

